_ib_run_bootstrap() {
  set +e
  _ib_out=$("<OPERATOR_REPO_PATH>/plugins/cache/larch-local/larch/47.0.12/scripts/implement-bootstrap.sh" --up-to-phase coder --issue-number "$TARGET_ISSUE_NUMBER" --preflight-tmpdir "$PREFLIGHT_TMPDIR" --emergency-requested "$emergency_requested")
